{
  "actions": [
    {
      "action": "Enforce expiry locally, including during outages",
      "mechanism": "Conservative clock deadlines and bounded screen-clearing latency prevent expired content from lingering without connectivity.",
      "implementation": "Clear each expiring item by local expiry minus 30 seconds; initiate clearing earlier by the enforced rendering-latency bound. Revalidate before resume.",
      "check": "Test both clock-error extremes, six-hour outages, stalled rendering, and sleep/resume; verify no item remains visible past its actual expiry.",
      "risk": "Items disappear early; frozen displays require a functioning blanking watchdog."
    },
    {
      "action": "Make reconnection replace, not merge, cached configuration",
      "mechanism": "Authoritative snapshots and durable monotonic generations reject rollback; omitted IDs are removed rather than retained.",
      "implementation": "Publish complete snapshots with increasing generations. Persist snapshot and generation atomically. Server-side revision floors prohibit republishing revoked revisions; devices reject older generations.",
      "check": "Remove an item, reconnect, replay an older snapshot, and reboot mid-update; the removed revision must never reappear after removal commits.",
      "risk": "Device state loss needs authoritative bootstrap; offline emergency removal remains impossible."
    },
    {
      "action": "Stage and validate bundles before making them visible",
      "mechanism": "An isolated candidate configuration prevents partial downloads or failed validation from changing the active announcement set.",
      "implementation": "Cap encoded bundles below 100,000 bytes at publication and receipt. Validate completeness, unique IDs, revisions, and validity fields before atomic activation.",
      "check": "Inject truncated, oversized, duplicate-ID, and malformed bundles; verify rejection leaves the previous configuration active with local expiry enforcement intact.",
      "risk": "Oversized configurations need explicit publication failure, never silent truncation."
    },
    {
      "action": "Show freshness limits alongside offline announcements",
      "mechanism": "Separate connectivity status from configuration age and distinguish timed validity from unknown revocation status.",
      "implementation": "Display last successful authoritative verification and offline status. State: “Timed announcements expire locally; until-revoked announcements may have been withdrawn while offline.”",
      "check": "During a six-hour outage, verify status persists, expired items disappear, and until-revoked items never receive an unqualified “current” label.",
      "risk": "Freshness notices consume display space and cannot establish whether revocation occurred."
    }
  ],
  "abstention_reason": ""
}
